class Solution:
    def encode(self, strs: List[str]) -> str:
      # result=""
      # for _ in strs:
      #   result = result + str(len(_)) + "^" + _ + "^"
      # return result
      result =[]
      for _ in strs:
        result.append(str(len(_)) + "^")
        result.append(_ + "^")
      return "".join(result)

# ["Hello","World"]
# 5^Hello^5^World^

    def decode(self, s: str) -> List[str]:
      result =[]
      i = 0
      while i< len(s):
        indxdel =  s.find("^",i)
        # indxdel = i
        # while indxdel < len(s) and s[indxdel] != "^":
        #   indxdel += 1
        length = int(s[i:indxdel])
        i = indxdel+1
        result.append(s[i:i+length])
        i = i + length + 1
      return result
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          

